#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 *
 * This version uses a Halide pipeline with an explicit schedule:
 *  - x (column / j) is vectorized.
 *  - y (row / i) is split and parallelized across scanlines.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    Expr n_expr = cast<num_t>(n);
    init_u(x, y) = (cast<num_t>(y) + n_expr - cast<num_t>(x)) / n_expr;

    // Simple but effective schedule: parallelize in y, vectorize in x.
    Target target   = get_jit_target_from_environment();
    int vec_width   = natural_vector_size<num_t>(target);
    Var yo("yo"), yi("yi");

    init_u
        .split(y, yo, yi, 32)   // 32-row tiles
        .parallel(yo)           // each tile in parallel
        .vectorize(x, vec_width);

    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * NOTE on Halide usage:
 * ---------------------
 * The ADI kernel consists of two tridiagonal solves per time step
 * (column sweep and row sweep). Each solve is inherently sequential
 * along one dimension (Thomas algorithm), i.e. loop-carried
 * dependencies like:
 *
 *     p[i][j] depends on p[i][j-1]
 *     v[i][j] depends on v[i][j+1]
 *
 * Halide's pure functional model does not allow these general
 * non-associative recurrences to be expressed as a single Func with
 * an RDom update (see tutorial lesson 9 rules). For this reason,
 * the core time-stepping loop is kept as explicit C++ loops over
 * Halide::Buffer objects, while stateless, data-parallel work such
 * as initialization is expressed as Halide pipelines (see init_array).
 *
 * This preserves the original numerical algorithm exactly while
 * still leveraging Halide where it is a good fit.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // Precompute scalars once.
    const num_t one  = num_t(1.0);
    const num_t two  = num_t(2.0);
    const num_t DX   = one / num_t(n);
    const num_t DY   = one / num_t(n);
    const num_t DT   = one / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = one + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = one + mul2;
    const num_t f = d;

    const num_t one_plus_2d = one + two * d;
    const num_t one_plus_2a = one + two * a;

    const int n_minus_1 = n - 1;
    const int n_minus_2 = n - 2;

    // Time-stepping loop (kept as explicit loops due to sequential
    // tridiagonal solves; see comment above).
    for (int t = 1; t <= tsteps; t++) {

        // ------------------------------------------------------------
        // Column sweep
        // ------------------------------------------------------------
        // Each original C iteration:
        //   for (i = 1; i < n-1; i++) { ... along j ... }
        // Here we keep the same ordering: y == i (slow), x == j (fast).
        for (int i = 1; i < n_minus_1; i++) {
            // v[0][i] = 1.0;
            v(i, 0) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = v[0][i];
            q(0, i) = v(i, 0);

            // Forward sweep along j
            // p[i][j] and q[i][j] depend only on the previous j
            // for the same i, so this loop must remain sequential.
            for (int j = 1; j < n_minus_1; j++) {
                // p[i][j] = -c / (a * p[i][j-1] + b);
                const num_t denom = a * p(j - 1, i) + b;
                const num_t p_ij  = -c / denom;
                p(j, i) = p_ij;

                // q[i][j] =
                //   (-d * u[j][i-1]
                //    + (1 + 2*d) * u[j][i]
                //    - f * u[j][i+1]
                //    - a * q[i][j-1]) /
                //   (a * p[i][j-1] + b);
                const num_t num =
                    -d * u(i - 1, j) +
                    one_plus_2d * u(i, j) -
                    f * u(i + 1, j) -
                    a * q(j - 1, i);

                q(j, i) = num / denom;
            }

            // v[n-1][i] = 1.0;
            v(i, n_minus_1) = one;

            // Back substitution along j (descending)
            for (int j = n_minus_2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v(i, j) = p(j, i) * v(i, j + 1) + q(j, i);
            }
        }

        // ------------------------------------------------------------
        // Row sweep
        // ------------------------------------------------------------
        for (int i = 1; i < n_minus_1; i++) {
            // u[i][0] = 1.0;
            u(0, i) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = u[i][0];
            q(0, i) = u(0, i);

            // Forward sweep along j
            for (int j = 1; j < n_minus_1; j++) {
                // p[i][j] = -f / (d * p[i][j-1] + e);
                const num_t denom = d * p(j - 1, i) + e;
                const num_t p_ij  = -f / denom;
                p(j, i) = p_ij;

                // q[i][j] =
                //   (-a * v[i-1][j]
                //    + (1 + 2*a) * v[i][j]
                //    - c * v[i+1][j]
                //    - d * q[i][j-1]) /
                //   (d * p[i][j-1] + e);
                const num_t num =
                    -a * v(j, i - 1) +
                    one_plus_2a * v(j, i) -
                    c * v(j, i + 1) -
                    d * q(j - 1, i);

                q(j, i) = num / denom;
            }

            // u[i][n-1] = 1.0;
            u(n_minus_1, i) = one;

            // Back substitution along j (descending)
            for (int j = n_minus_2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u(j, i) = p(j, i) * u(j + 1, i) + q(j, i);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
