#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 */
static void init_array(int n, Halide::Buffer<num_t, 2> &u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    // Simple, cache-friendly schedule: vectorize across x (fast dim) and
    // parallelize across y (outer dim). The exact factor is a compromise
    // between portability and exploiting SIMD on x86-64.
    const int vec_width = 8;
    init_u.vectorize(x, vec_width).parallel(y);

    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * NOTE: The algorithm contains strong loop-carried dependences along the
 *       "j" dimension (Thomas algorithm / tridiagonal solves). These cannot
 *       be expressed as a single pure Halide reduction without violating
 *       Halide's update rules, so we follow the recommended pattern for
 *       dynamic-programming-style code: keep the recurrence in host loops,
 *       but optimize the memory access pattern and arithmetic carefully.
 *       All array storage is still managed via Halide::Buffer.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> &u,
                       Halide::Buffer<num_t, 2> &v,
                       Halide::Buffer<num_t, 2> &p,
                       Halide::Buffer<num_t, 2> &q) {
    // Scalar coefficients (identical to the original code, but hoisted).
    const num_t one = num_t(1.0);
    const num_t two = num_t(2.0);

    const num_t DX   = one / num_t(n);
    const num_t DY   = one / num_t(n);
    const num_t DT   = one / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = one + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = one + mul2;
    const num_t f = d;

    // Frequently used composite coefficients.
    const num_t center_col = one + two * d; // (1 + 2*d) in column sweep
    const num_t center_row = one + two * a; // (1 + 2*a) in row sweep

    const int n_minus_1 = n - 1;
    const int n_minus_2 = n - 2;

    // Strides for generic (possibly non-contiguous) Halide::Buffer layouts.
    // For the default construction used in main(), we have:
    //   stride(0) == 1, stride(1) == n
    // but we don't rely on that explicitly.
    const int u_s0 = u.stride(0); // step in first index
    const int u_s1 = u.stride(1); // step in second index
    const int v_s0 = v.stride(0);
    const int v_s1 = v.stride(1);
    const int p_s0 = p.stride(0);
    const int q_s0 = q.stride(0);
    const int p_s1 = p.stride(1); // currently unused, kept for clarity
    const int q_s1 = q.stride(1); // currently unused, kept for clarity
    (void)p_s1;
    (void)q_s1;

    // Time-stepping loop (loop-carried dependency across t).
    for (int t = 1; t <= tsteps; ++t) {

        // ------------------------------------------------------------
        // Column sweep
        // ------------------------------------------------------------
        //
        // For each i, we perform a forward sweep along j to compute p and q,
        // then a backward substitution along j to update v. The dependence
        // is strictly along j, so we keep i as the outer loop and optimize
        // memory access within each sweep using raw pointers and precomputed
        // strides.
        for (int i = 1; i < n_minus_1; ++i) {
            // v[0][i] = 1.0;
            v(i, 0) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = v[0][i];
            q(0, i) = v(i, 0); // == one

            // --------------------------
            // Forward sweep along j
            // --------------------------
            //
            // Recurrence:
            //   denom = a * p[i][j-1] + b;
            //   p[i][j] = -c / denom;
            //   q[i][j] =
            //     (-d * u[j-1][i]
            //      + (1 + 2*d) * u[j][i]
            //      - f * u[j+1][i]
            //      - a * q[i][j-1]) / denom;
            //
            // Translated to Buffer indexing as in the original code.

            // Pointers along j (first index of p and q).
            num_t *p_prev = &p(0, i);           // p(i, j-1) at j=1
            num_t *q_prev = &q(0, i);           // q(i, j-1)
            num_t *p_cur  = p_prev + p_s0;      // p(i, j)   at j=1
            num_t *q_cur  = q_prev + q_s0;      // q(i, j)

            // Pointers stepping along the second index of u: u(i-1,j), u(i,j), u(i+1,j).
            num_t *u_im1 = &u(i - 1, 1);
            num_t *u_i   = &u(i,     1);
            num_t *u_ip1 = &u(i + 1, 1);

            for (int j = 1; j < n_minus_1; ++j) {
                const num_t denom = a * (*p_prev) + b;

                *p_cur = -c / denom;

                const num_t num =
                    -d * (*u_im1) +
                    center_col * (*u_i) -
                    f * (*u_ip1) -
                    a * (*q_prev);

                *q_cur = num / denom;

                // Advance all pointers to the next j.
                p_prev = p_cur;
                q_prev = q_cur;
                p_cur  += p_s0;
                q_cur  += q_s0;

                u_im1 += u_s1;
                u_i   += u_s1;
                u_ip1 += u_s1;
            }

            // v[n-1][i] = 1.0;
            v(i, n_minus_1) = one;

            // --------------------------
            // Back substitution along j
            // --------------------------
            //
            // Recurrence:
            //   v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
            //
            // j descends from n-2 down to 1.

            num_t *v_next = &v(i, n_minus_1);        // v(i, j+1) at j = n-2 (v[n-1][i])
            num_t *v_curr = v_next - v_s1;           // v(i, j)   at j = n-2
            num_t *p_j    = &p(n_minus_2, i);        // p(i, j)
            num_t *q_j    = &q(n_minus_2, i);        // q(i, j)

            for (int j = n_minus_2; j >= 1; --j) {
                *v_curr = (*p_j) * (*v_next) + (*q_j);

                v_next = v_curr;
                v_curr -= v_s1;
                p_j    -= p_s0;
                q_j    -= q_s0;
            }
        }

        // ------------------------------------------------------------
        // Row sweep
        // ------------------------------------------------------------
        //
        // Completely analogous to the column sweep, but now operating
        // along the "other" spatial dimension and updating u instead of v.
        for (int i = 1; i < n_minus_1; ++i) {
            // u[i][0] = 1.0;
            u(0, i) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = u[i][0];
            q(0, i) = u(0, i); // == one

            // --------------------------
            // Forward sweep along j
            // --------------------------
            //
            // Recurrence:
            //   denom = d * p[i][j-1] + e;
            //   p[i][j] = -f / denom;
            //   q[i][j] =
            //     (-a * v[i-1][j]
            //      + (1 + 2*a) * v[i][j]
            //      - c * v[i+1][j]
            //      - d * q[i][j-1]) / denom;

            num_t *p_prev = &p(0, i);
            num_t *q_prev = &q(0, i);
            num_t *p_cur  = p_prev + p_s0;
            num_t *q_cur  = q_prev + q_s0;

            // v(i-1,j), v(i,j), v(i+1,j) vary along j (first index).
            num_t *v_im1 = &v(1, i - 1);
            num_t *v_i   = &v(1, i);
            num_t *v_ip1 = &v(1, i + 1);

            for (int j = 1; j < n_minus_1; ++j) {
                const num_t denom = d * (*p_prev) + e;
                *p_cur = -f / denom;

                const num_t num =
                    -a * (*v_im1) +
                    center_row * (*v_i) -
                    c * (*v_ip1) -
                    d * (*q_prev);

                *q_cur = num / denom;

                // Advance along j.
                p_prev = p_cur;
                q_prev = q_cur;
                p_cur  += p_s0;
                q_cur  += q_s0;

                v_im1 += v_s0;
                v_i   += v_s0;
                v_ip1 += v_s0;
            }

            // u[i][n-1] = 1.0;
            u(n_minus_1, i) = one;

            // --------------------------
            // Back substitution along j
            // --------------------------
            //
            // Recurrence:
            //   u[i][j] = p[i][j] * u[i][j+1] + q[i][j];

            num_t *u_next = &u(n_minus_1, i);       // u(j+1,i) at j = n-2
            num_t *u_curr = u_next - u_s0;          // u(j,i)   at j = n-2
            num_t *p_j    = &p(n_minus_2, i);
            num_t *q_j    = &q(n_minus_2, i);

            for (int j = n_minus_2; j >= 1; --j) {
                *u_curr = (*p_j) * (*u_next) + (*q_j);

                u_next = u_curr;
                u_curr -= u_s0;
                p_j    -= p_s0;
                q_j    -= q_s0;
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
