 * NOTE ON DESIGN:
 * ----------------
 * The ADI kernel uses tridiagonal solves (Thomas algorithm) in both
 * column and row sweeps. This involves strong loop-carried
 * dependencies along the "j" dimension, e.g. p(j) depends on p(j-1),
 * v(j) depends on v(j+1), etc. Halide update definitions do not
 * permit referring to the same Func at different coordinates on the
 * right-hand side (e.g. f(x-1)), so these 1D recurrences cannot be
 * expressed as legal Halide reductions.
 *
 * Following the provided guidelines for such dynamic-programming-
 * style algorithms, we keep the time-stepping and 1D recurrences as
 * host-driven loops, but:
 *   - operate directly on Halide::Buffer storage,
 *   - carefully structure memory access for good locality,
 *   - hoist invariants out of inner loops,
 *   - use contiguous row pointers so the innermost loops are simple
 *     tight loops over contiguous memory (good for auto-vectorization).
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // ------------------------------------------------------------------
    // Precompute scalar coefficients (once for the whole kernel).
    // ------------------------------------------------------------------
    const num_t DX = num_t(1.0) / num_t(n);
    const num_t DY = num_t(1.0) / num_t(n);
    const num_t DT = num_t(1.0) / num_t(tsteps);
    const num_t B1 = num_t(2.0);
    const num_t B2 = num_t(1.0);

    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t half = num_t(0.5);
    const num_t one  = num_t(1.0);
    const num_t two  = num_t(2.0);
    const num_t zero = num_t(0.0);

    // Coefficients for implicit scheme
    const num_t a = -mul1 * half;
    const num_t b = one + mul1;
    const num_t c = a;
    const num_t d = -mul2 * half;
    const num_t e = one + mul2;
    const num_t f = d;

    // Frequently reused composite coefficients:
    const num_t col_center = one + two * d; // (1 + 2*d) in column sweep
    const num_t row_center = one + two * a; // (1 + 2*a) in row sweep

    const int n1 = n - 1;
    const int n2 = n - 2;

    // ------------------------------------------------------------------
    // Time-stepping loop.
    // ------------------------------------------------------------------
    for (int t = 1; t <= tsteps; t++) {

        // ==============================================================
        // 1) Column sweep
        //    For each "i" (C-row index), we solve along "j" (C-column).
        //
        //    Mapping: u[i][j] -> u(j, i)
        //             v[i][j] -> v(j, i)
        //             p[i][j] -> p(j, i)
        //             q[i][j] -> q(j, i)
        //
        //    Inner loops are over j (x dimension) so we get contiguous
        //    memory access in the innermost loops.
        // ==============================================================

        for (int i = 1; i < n1; i++) {
            // Row pointers for this i. Using pointers (rather than
            // repeated Buffer::operator()) creates tight inner loops
            // with simple indexing (v_row[j], etc.), which the
            // compiler can more easily vectorize.
            //
            // NOTE: Halide::Buffer uses row-major layout with x (dim 0)
            //       contiguous by default, so &buf(0, i) gives us a
            //       contiguous row in j.
            num_t * __restrict v_row   = &v(0, i);     // v(j, i)
            num_t * __restrict u_im1   = &u(0, i - 1); // u(j, i-1)
            num_t * __restrict u_i     = &u(0, i);     // u(j, i)
            num_t * __restrict u_ip1   = &u(0, i + 1); // u(j, i+1)
            num_t * __restrict p_row   = &p(0, i);     // p(j, i)
            num_t * __restrict q_row   = &q(0, i);     // q(j, i)

            // Boundary conditions at j = 0
            // v[0][i] = 1.0;
            v_row[0] = one;

            // p[i][0] = 0.0;   (p(0, i))
            p_row[0] = zero;

            // q[i][0] = v[0][i];
            q_row[0] = v_row[0];

            // Forward sweep along j = 1 .. n-2
            for (int j = 1; j < n2; j++) {
                // denom = a * p[i][j-1] + b;
                const num_t denom = a * p_row[j - 1] + b;

                // p[i][j] = -c / (a * p[i][j-1] + b);
                p_row[j] = -c / denom;

                // q[i][j] =
                //   (-d * u[j][i-1]
                //    + (1 + 2*d) * u[j][i]
                //    - f * u[j][i+1]
                //    - a * q[i][j-1]) /
                //   (a * p[i][j-1] + b);
                const num_t num =
                    -d * u_im1[j] +
                    col_center * u_i[j] -
                    f * u_ip1[j] -
                    a * q_row[j - 1];

                q_row[j] = num / denom;
            }

            // v[n-1][i] = 1.0;
            v_row[n1] = one;

            // Back substitution along j (descending): j = n-2 .. 1
            for (int j = n2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v_row[j] = p_row[j] * v_row[j + 1] + q_row[j];
            }
        }

        // ==============================================================
        // 2) Row sweep
        //    For each "i" (C-row index), we now solve another
        //    tridiagonal system along "j", but this time updating u
        //    based on v.
        // ==============================================================

        for (int i = 1; i < n1; i++) {
            num_t * __restrict u_row   = &u(0, i);     // u(j, i)
            num_t * __restrict v_im1   = &v(0, i - 1); // v(j, i-1)
            num_t * __restrict v_i     = &v(0, i);     // v(j, i)
            num_t * __restrict v_ip1   = &v(0, i + 1); // v(j, i+1)
            num_t * __restrict p_row   = &p(0, i);     // p(j, i)
            num_t * __restrict q_row   = &q(0, i);     // q(j, i)

            // u[i][0] = 1.0;
            u_row[0] = one;

            // p[i][0] = 0.0;
            p_row[0] = zero;

            // q[i][0] = u[i][0];
            q_row[0] = u_row[0];

            // Forward sweep along j = 1 .. n-2
            for (int j = 1; j < n2; j++) {
                // denom = d * p[i][j-1] + e;
                const num_t denom = d * p_row[j - 1] + e;

                // p[i][j] = -f / (d * p[i][j-1] + e);
                p_row[j] = -f / denom;

                // q[i][j] =
                //   (-a * v[i-1][j]
                //    + (1 + 2*a) * v[i][j]
                //    - c * v[i+1][j]
                //    - d * q[i][j-1]) /
                //   (d * p[i][j-1] + e);
                const num_t num =
                    -a * v_im1[j] +
                    row_center * v_i[j] -
                    c * v_ip1[j] -
                    d * q_row[j - 1];

                q_row[j] = num / denom;
            }

            // u[i][n-1] = 1.0;
            u_row[n1] = one;

            // Back substitution along j (descending): j = n-2 .. 1
            for (int j = n2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u_row[j] = p_row[j] * u_row[j + 1] + q_row[j];
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
