 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    // Simple but effective schedule: vectorize over x (fast dim), parallelize over y.
    init_u
        .vectorize(x, 8)
        .parallel(y);

    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * NOTE:
 * -----
 * The ADI scheme uses 1D tridiagonal solves (Thomas algorithm) along rows
 * and columns. These are inherently sequential along the sweep direction,
 * so we keep the per-line recurrences as explicit C++ loops, but:
 *
 *   - We aggressively hoist loop-invariant constants.
 *   - We express all 2D array accesses via the Halide::Buffer layout
 *     (using its strides) to avoid repeated index recomputation.
 *   - We parallelize across the independent sweep dimension (i) using
 *     a parallel-for style implemented via std::thread/async-like
 *     semantics in Halide-inspired fashion (simple OpenMP pragmas are
 *     used when available; they are ignored otherwise).
 *
 * This preserves the original numerical algorithm while improving
 * cache locality and enabling multi-core execution.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // -------------------------------------------------------------------------
    // Precompute scalar parameters (loop-invariant)
    // -------------------------------------------------------------------------
    const num_t DX = num_t(1.0) / num_t(n);
    const num_t DY = num_t(1.0) / num_t(n);
    const num_t DT = num_t(1.0) / num_t(tsteps);

    const num_t B1 = num_t(2.0);
    const num_t B2 = num_t(1.0);

    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = num_t(1.0) + mul1;
    const num_t c = a;

    const num_t d = -mul2 / num_t(2.0);
    const num_t e = num_t(1.0) + mul2;
    const num_t f = d;

    const num_t one = num_t(1.0);
    const num_t zero = num_t(0.0);
    const num_t two = num_t(2.0);

    // Frequently used combinations
    const num_t one_plus_2d = one + two * d;
    const num_t one_plus_2a = one + two * a;

    // -------------------------------------------------------------------------
    // Extract raw pointers and strides from Halide::Buffer
    // -------------------------------------------------------------------------
    num_t *const u_data = u.data();
    num_t *const v_data = v.data();
    num_t *const p_data = p.data();
    num_t *const q_data = q.data();

    const int u_s0 = u.stride(0); // x stride
    const int u_s1 = u.stride(1); // y stride
    const int v_s0 = v.stride(0);
    const int v_s1 = v.stride(1);
    const int p_s0 = p.stride(0);
    const int p_s1 = p.stride(1);
    const int q_s0 = q.stride(0);
    const int q_s1 = q.stride(1);

    // We rely on the default Halide layout where the first dimension is
    // contiguous in memory; assert this in debug builds.
#ifndef NDEBUG
    assert(u_s0 == 1 && v_s0 == 1 && p_s0 == 1 && q_s0 == 1);
#endif

    // Helper lambdas to get pointers to "columns" (fixed x) or "rows" (fixed y)
    auto col_ptr = [](num_t *base, int x, int s0, int s1) -> num_t * {
        // Points at (x, 0) so that element (x, y) is col_ptr[y * s1]
        return base + x * s0;
    };
    auto row_ptr = [](num_t *base, int y, int s0, int s1) -> num_t * {
        // Points at (0, y) so that element (x, y) is row_ptr[x * s0]
        return base + y * s1;
    };

    // -------------------------------------------------------------------------
    // Time-stepping loop
    // -------------------------------------------------------------------------
    for (int t = 1; t <= tsteps; t++) {

        // ============================================================
        // Column sweep (matches original algorithm)
        // ============================================================
        //
        // for (i = 1; i < n-1; i++) {
        //   v[0][i] = 1.0;
        //   p[i][0] = 0.0;
        //   q[i][0] = v[0][i];
        //   for (j = 1; j < n-1; j++) {
        //     ...
        //   }
        //   v[n-1][i] = 1.0;
        //   for (j = n-2; j >= 1; j--) {
        //     ...
        //   }
        // }

        // Each i-sweep is independent, so we parallelize over i.
        // If compiled without OpenMP, the pragma is ignored by the compiler.
#pragma omp parallel for schedule(static)
        for (int i = 1; i < n - 1; i++) {
            // Column-oriented views (vary y, fixed x)
            num_t *const v_col = col_ptr(v_data, i, v_s0, v_s1);
            num_t *const p_col = col_ptr(p_data, i, p_s0, p_s1);
            num_t *const q_col = col_ptr(q_data, i, q_s0, q_s1);

            // Neighboring columns of u used in the stencil
            num_t *const u_col_im1 = col_ptr(u_data, i - 1, u_s0, u_s1);
            num_t *const u_col_i   = col_ptr(u_data, i,     u_s0, u_s1);
            num_t *const u_col_ip1 = col_ptr(u_data, i + 1, u_s0, u_s1);

            // Boundary conditions along the sweep
            // v[0][i] = 1.0;  -> v(i, 0)
            v_col[0 * v_s1] = one;

            // p[i][0] = 0.0; -> p(0, i)
            p_col[0 * p_s1] = zero;

            // q[i][0] = v[0][i]; -> q(0, i) = v(i, 0)
            q_col[0 * q_s1] = v_col[0 * v_s1];

            // Forward sweep along j (1 .. n-2)
            for (int j = 1; j < n - 1; j++) {
                const int idx_prev = (j - 1) * p_s1;
                const int idx_curr = j * p_s1;

                const num_t denom = a * p_col[idx_prev] + b;
                const num_t p_val = -c / denom;
                p_col[idx_curr] = p_val;

                // Access u at (i-1,j), (i,j), (i+1,j) via column pointers
                const num_t u_im1j = u_col_im1[j * u_s1];
                const num_t u_ij   = u_col_i  [j * u_s1];
                const num_t u_ip1j = u_col_ip1[j * u_s1];

                const num_t num =
                    -d * u_im1j +
                    one_plus_2d * u_ij -
                    f * u_ip1j -
                    a * q_col[idx_prev];

                q_col[j * q_s1] = num / denom;
            }

            // v[n-1][i] = 1.0; -> v(i, n-1)
            v_col[(n - 1) * v_s1] = one;

            // Back substitution along j (n-2 .. 1)
            for (int j = n - 2; j >= 1; j--) {
                const int idx_j   = j * p_s1;
                const int idx_jp1 = (j + 1) * v_s1;
                const int idx_vj  = j * v_s1;
                const int idx_qj  = j * q_s1;

                v_col[idx_vj] = p_col[idx_j] * v_col[idx_jp1] + q_col[idx_qj];
            }
        }

        // ============================================================
        // Row sweep
        // ============================================================
        //
        // for (i = 1; i < n-1; i++) {
        //   u[i][0] = 1.0;
        //   p[i][0] = 0.0;
        //   q[i][0] = u[i][0];
        //   for (j = 1; j < n-1; j++) {
        //     ...
        //   }
        //   u[i][n-1] = 1.0;
        //   for (j = n-2; j >= 1; j--) {
        //     ...
        //   }
        // }

#pragma omp parallel for schedule(static)
        for (int i = 1; i < n - 1; i++) {
            // Row-oriented view of u: fixed y = i, vary x
            num_t *const u_row   = row_ptr(u_data, i, u_s0, u_s1);
            num_t *const p_col   = col_ptr(p_data, i, p_s0, p_s1);
            num_t *const q_col   = col_ptr(q_data, i, q_s0, q_s1);
            num_t *const v_row_im1 = row_ptr(v_data, i - 1, v_s0, v_s1);
            num_t *const v_row_i   = row_ptr(v_data, i,     v_s0, v_s1);
            num_t *const v_row_ip1 = row_ptr(v_data, i + 1, v_s0, v_s1);

            // u[i][0] = 1.0; -> u(0, i)
            u_row[0 * u_s0] = one;

            // p[i][0] = 0.0; -> p(0, i)
            p_col[0 * p_s1] = zero;

            // q[i][0] = u[i][0]; -> q(0, i)
            q_col[0 * q_s1] = u_row[0 * u_s0];

            // Forward sweep along j (1 .. n-2)
            for (int j = 1; j < n - 1; j++) {
                const int idx_prev = (j - 1) * p_s1;
                const int idx_curr = j * p_s1;

                const num_t denom = d * p_col[idx_prev] + e;
                const num_t p_val = -f / denom;
                p_col[idx_curr] = p_val;

                // Access v at (i-1,j), (i,j), (i+1,j) using row pointers
                const num_t v_im1j = v_row_im1[j * v_s0];
                const num_t v_ij   = v_row_i  [j * v_s0];
                const num_t v_ip1j = v_row_ip1[j * v_s0];

                const num_t num =
                    -a * v_im1j +
                    one_plus_2a * v_ij -
                    c * v_ip1j -
                    d * q_col[idx_prev];

                q_col[j * q_s1] = num / denom;
            }

            // u[i][n-1] = 1.0; -> u(n-1, i)
            u_row[(n - 1) * u_s0] = one;

            // Back substitution along j (n-2 .. 1)
            for (int j = n - 2; j >= 1; j--) {
                const int idx_j   = j * p_s1;
                const int idx_jp1 = (j + 1) * u_s0;
                const int idx_uj  = j * u_s0;
                const int idx_qj  = j * q_s1;

                u_row[idx_uj] = p_col[idx_j] * u_row[idx_jp1] + q_col[idx_qj];
            }
        }
    }
}

